// JAH demo program — Walking the garden
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var __steps=["List the live possibilities", "Notice which futures your habits water", "Prune deliberately \u2014 choose", "Tend the chosen branch"];
__steps.forEach(function(s,i){console.log("step "+(i+1)+": "+s);});
check("step count", __steps.length, 4);
function tended(choices){ return choices>0?'garden growing':'walk the garden'; }
check("choices made", tended(3), "garden growing");
check("no choice", tended(0), "walk the garden");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

